import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007;

    static long fastPow(long base, long exp, long mod) {
        long res = 1;
        long b = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * b) % mod;
            }
            b = (b * b) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        if (m == 0) {
            System.out.println(fastPow(n, n - 1, MOD));
        } else if (m == 1) {
            System.out.println(fastPow(n, n, MOD));
        } else {
            long[] parent = new long[(int) n + 1];
            int[] rank = new int[(int) n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
                rank[i] = 0;
            }

            // find function with path compression
            class UnionFind {
                long find(long x) {
                    while (parent[(int) x] != x) {
                        parent[(int) x] = parent[(int) parent[(int) x]];
                        x = parent[(int) x];
                    }
                    return x;
                }

                void unite(long a, long b) {
                    long pa = find(a);
                    long pb = find(b);
                    if (pa != pb) {
                        if (rank[(int) pa] >= rank[(int) pb]) {
                            parent[(int) pb] = pa;
                            if (rank[(int) pa] == rank[(int) pb]) {
                                rank[(int) pa]++;
                            }
                        } else {
                            parent[(int) pa] = pb;
                        }
                    }
                }
            }

            UnionFind uf = new UnionFind();

            for (long i = 1; i < n; i++) {
                long b = (i * m) % n;
                uf.unite(i, b);
            }

            Set<Long> distinctRoots = new HashSet<>();
            for (long i = 1; i < n; i++) {
                distinctRoots.add(uf.find(i));
            }
            long countRoots = distinctRoots.size();
            System.out.println(fastPow(n, countRoots, MOD));
        }
    }
}
